import sys


def solve(data=None) -> None:
    if data is None:
        data = sys.stdin.read().split()
    pos = 0
    if pos >= len(data):
        return
    H = int(data[pos]); pos += 1
    if pos >= len(data):
        return
    W = int(data[pos]); pos += 1
    if pos >= len(data):
        return
    k = int(data[pos]); pos += 1

    # 读取初始网格 (每行 W 个字符, 只含 '.' 与 '#')
    grid = []
    for _ in range(H):
        row = data[pos]; pos += 1
        grid.append([1 if ch == '#' else 0 for ch in row])

    # 同时按 8 邻域模拟 k 代; 网格外视为死格
    for _ in range(k):
        nxt = [[0] * W for _ in range(H)]
        for r in range(H):
            for c in range(W):
                # 统计 8 邻域活细胞数 (越界跳过 => 死格)
                n = 0
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        rr = r + dr
                        cc = c + dc
                        if 0 <= rr < H and 0 <= cc < W and grid[rr][cc]:
                            n += 1
                if grid[r][c]:
                    # 活细胞: 邻居 2 或 3 存活, 否则死亡
                    nxt[r][c] = 1 if (n == 2 or n == 3) else 0
                else:
                    # 死细胞: 邻居恰为 3 复活
                    nxt[r][c] = 1 if n == 3 else 0
        grid = nxt

    out = []
    for r in range(H):
        out.append(''.join('#' if v else '.' for v in grid[r]))
    sys.stdout.write('\n'.join(out) + '\n')


def _run_selftest() -> int:
    import io
    cases = [
        (
            "3 3 1\n...\n.#.\n...\n",
            "...\n...\n...\n",
        ),
        (
            "5 5 0\n.....\n..#..\n.###.\n.....\n.....\n",
            ".....\n..#..\n.###.\n.....\n.....\n",
        ),
        (
            "3 3 1\n###\n###\n###\n",
            ".#.\n.#.\n.#.\n",
        ),
    ]
    ok = True
    for inp, exp in cases:
        old_in, old_out = sys.stdin, sys.stdout
        sys.stdin = io.StringIO(inp)
        sys.stdout = io.StringIO()
        try:
            solve()
            got = sys.stdout.getvalue()
        finally:
            sys.stdin, sys.stdout = old_in, old_out
        if got == exp:
            print("PASS")
        else:
            ok = False
            print("FAIL")
    print("TOTAL: " + ("PASS" if ok else "FAIL"))
    return 0 if ok else 1


if __name__ == '__main__':
    if '--selftest' in sys.argv:
        sys.exit(_run_selftest())
    solve()
